SourceCode.Declaration:
[DataContractAttribute]
class HSMobileOpsSerialResponse
{
    boolean success;
    str     errorCode;
    boolean registered;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

/// <summary>
/// True when D365FO already knows this serial for this item. The client refuses the scan.
/// </summary>
[DataMemberAttribute('Registered')]
public boolean parmRegistered(boolean _value = registered)
{
    registered = _value;
    return registered;
}
